function assert2(expression, message) {
  if (!expression) {
    error(message);
    process.exit(1);
  }
}
async function checkApiLock() {
  info(`${NEMO_LOCK} \u6587\u4EF6\u68C0\u6D4B\u4E2D...`);
  const manager = await createManager();
  if (!manager) {
    info(`${NEMO_LOCK} \u6587\u4EF6\u68C0\u6D4B\u5931\u8D25\uFF0C\u8BF7\u786E\u8BA4\uFF01`);
    return;
  }
  const localDatas = await manager.readLockFile();
  try {
    if (localDatas.length > 1) {
      assert2(
        localDatas.every((data) => !!data.name),
        "\u591A\u6570\u636E\u6E90\u6BCF\u4E2A\u6570\u636E\u6E90\u5E94\u8BE5\u6709\u300Cname\u300D"
      );
    }
    localDatas.forEach((data) => {
      data.baseClasses.forEach((base) => {
        assert2(!!base.name, `\u63CF\u8FF0\u4E3A ${base.description} \u7684\u7C7B\u6CA1\u6709\u300Cname\u300D\u5C5E\u6027`);
        base.properties.forEach((prop) => {
          assert2(!!prop.name, `${base.name} \u7C7B\u7684\u67D0\u4E2A\u5C5E\u6027\u6CA1\u6709\u300Cname\u300D\u5C5E\u6027`);
        });
      });
      data.mods.forEach((mod) => {
        assert2(!!mod.name, `\u63CF\u8FF0\u4E3A ${mod.description} \u7684\u6A21\u5757\u6CA1\u6709\u300Cname\u300D\u5C5E\u6027`);
        mod.interfaces.forEach((inter) => {
          assert2(!!inter.name, `${mod.name} \u6A21\u5757\u7684\u67D0\u4E2A\u63A5\u53E3\u6CA1\u6709\u300Cname\u300D\u5C5E\u6027`);
          inter.parameters.forEach((param) => {
            assert2(!!param.name, `${mod.name} \u6A21\u5757\u7684 ${inter.name} \u63A5\u53E3\u7684\u67D0\u4E2A\u53C2\u6570\u6CA1\u6709 "name" \u5C5E\u6027`);
          });
        });
      });
    });
  } catch (e) {
    error(e);
    process.exit(1);
  }
  process.exit(0);
}

// src/action/diff.ts
var import_chalk2 = __toESM(require("chalk"));
async function diffDataSource() {
  const manager = await createManager();
  if (!manager) {
    info(`${NEMO_LOCK} \u6587\u4EF6\u68C0\u6D4B\u5931\u8D25\uFF0C\u8BF7\u786E\u8BA4\uFF01`);
    return;
  }
  manager.calDiffs();
  const { modDiffs, boDiffs } = manager.diffs;
  if (Array.isArray(modDiffs) && modDiffs.length) {
    console.log(`${import_chalk2.default.bgRedBright("\u6CE8\u610F\uFF1A\u6A21\u5757\u6709\u66F4\u65B0\uFF01!!")}`);
    console.log(`${import_chalk2.default.cyan("\u5177\u4F53\u4FE1\u606F\u5982\u4E0B\uFF1A")}`);
    console.log(modDiffs.map((mod) => `${import_chalk2.default.bold.yellow(mod.name)}(${mod.details.join("\n\r")})`).join("\n\r"));
  }
  if (Array.isArray(boDiffs) && boDiffs.length) {
    console.log("\n\r");
    console.log(`${import_chalk2.default.bgRedBright("\u6CE8\u610F\uFF1A\u57FA\u7C7B\u6709\u66F4\u65B0\uFF01!!")}`);
    console.log(`${import_chalk2.default.cyan("\u5177\u4F53\u4FE1\u606F\u5982\u4E0B\uFF1A")}`);
    console.log(boDiffs.map((bo) => `${import_chalk2.default.bold.magenta(bo.name)}(${bo.details.join("\n\r")})`).join("\n\r"));
  }
}

