// src/action/updateVersion.ts
var import_child_process2 = require("child_process");
var import_ora = __toESM(require_ora());
var checkLatestVersion = async () => {
  const npm = await npmType;
  const latestVersion = (0, import_child_process2.execSync)(`${npm} view ${PKG_NAME} version`).toString("utf-8").trim();
  if (PKG_VERSION === latestVersion)
    return null;
  const compareArr = PKG_VERSION.split(".").map(Number);
  const beComparedArr = latestVersion.split(".").map(Number);
  for (let i = 0; i < compareArr.length; i++) {
    if (compareArr[i] > beComparedArr[i]) {
      return null;
    } else if (compareArr[i] < beComparedArr[i]) {
      return latestVersion;
    }
  }
};
var updateVersion_default = async (install = true) => {
  const checking = (0, import_ora.default)(`[${PKG_NAME}] \u6B63\u5728\u68C0\u67E5\u6700\u65B0\u7248\u672C...`);
  checking.start();
  try {
    const npm = await npmType;
    const latestVersion = await checkLatestVersion();
    checking.stop();
    if (latestVersion && install) {
      const update = (0, import_ora.default)(`[${PKG_NAME}] \u5B58\u5728\u65B0\u7248\u672C\uFF0C\u5C06\u5347\u7EA7\u81F3 ${latestVersion}`);
      update.start();
      (0, import_child_process2.execSync)(`${npm} i -g ${PKG_NAME}`);
      update.stop();
    } else if (latestVersion) {
      warn(
        `\u6700\u65B0\u7248\u672C\u4E3A ${latestVersion}\uFF0C\u672C\u5730\u7248\u672C\u4E3A ${PKG_VERSION}\uFF0C\u8BF7\u5C3D\u5FEB\u5347\u7EA7\u5230\u6700\u65B0\u7248\u672C\u3002
\u4F60\u53EF\u4EE5\u6267\u884C ${npm} install -g ${PKG_NAME}@latest \u6765\u5B89\u88C5\u6B64\u7248\u672C
`
      );
    } else if (install) {
      info(`\u5F53\u524D\u6CA1\u6709\u53EF\u7528\u7684\u66F4\u65B0`);
    }
  } catch (e) {
    checking.stop();
    error(e);
  }
};

// src/action/scan.ts
var fs8 = __toESM(require("fs"));
var path9 = __toESM(require("path"));
function readDirRecursively(dirPath, callback) {
  fs8.readdirSync(dirPath).forEach((subPath) => {
    const currentPath = dirPath + "/" + subPath;
    const stat = fs8.lstatSync(currentPath);
    if (stat.isDirectory()) {
      readDirRecursively(currentPath, callback);
    } else {
      callback(currentPath);
    }
  });
}
async function scan() {
  info("service scanning...");
  const manager = await createManager();
  if (!manager) {
    info(`${NEMO_LOCK} \u6587\u4EF6\u68C0\u6D4B\u5931\u8D25\uFF0C\u8BF7\u786E\u8BA4\uFF01`);
    return;
  }
  const rootPath = process.cwd();
  const {
    currConfig,
    allLocalDataSources,
    fileManager: {
      fileStructures: { getApiUseCases }
    }
  } = manager;
  const allRequests = new Set(
    allLocalDataSources.map((ds) => ds.mods).reduce((acc, cur) => [...acc, ...cur], []).map((mod) => mod.interfaces).reduce((acc, cur) => [...acc, ...cur], [])
  );
  const unusedRequests = new Set(allRequests);
  const outputFileName = "./unusedRequests.json";
  currConfig.scannedRange.forEach((dir) => {
    readDirRecursively(dir, (currentPath) => {
      const fileContent = fs8.readFileSync(currentPath).toString();
      unusedRequests.forEach((inter) => {
        const useCases = getApiUseCases(inter);
        console.log("useCases", useCases);
        if (useCases.some((useCase) => fileContent.includes(useCase))) {
          unusedRequests.delete(inter);
        }
      });
    });
  });
  fs8.writeFileSync(
    outputFileName,
    JSON.stringify(
      [...unusedRequests].map(({ method, path: path10, description }) => ({ method, path: path10, description })),
      null,
      2
    )
  );
  info(`unused case percentage: ${unusedRequests.size} / ${allRequests.size}`);
  success(`done!
unused file is outputted to ${path9.resolve(rootPath, outputFileName)}`);
}

