// src/cli.ts
var program = new import_commander.Command();
program.version(PKG_VERSION, "-v, --version", "output the current version").name("nemo").usage("[\u547D\u4EE4] [\u914D\u7F6E\u9879]");
program.description("service interface api code generator via swagger schema.");
program.command("init").alias("i").description("nemo \u914D\u7F6E\u6587\u4EF6\u751F\u6210").action(generateNemoConfig);
program.command("check").alias("c").description(`\u68C0\u6D4B ${NEMO_LOCK} \u6587\u4EF6`).action(checkApiLock);
program.command("ls").alias("l").description("\u67E5\u770B\u6570\u636E\u6E90").action(queryDataSource);
program.command("diff").alias("d").description("\u5BF9\u6BD4\u6570\u636E\u6E90").action(diffDataSource);
program.command("select <dsName>").description("\u9009\u62E9\u6570\u636E\u6E90").alias("s").action((dsName) => {
  chooseDataSource(dsName);
});
program.command("updateBo <boName>").description("\u66F4\u65B0\u57FA\u7C7B").alias("ub").action((boName) => {
  updateBo(boName);
});
program.command("updateMod <modName>").alias("um").description("\u66F4\u65B0\u6A21\u5757").action((modName) => {
  updateMod(modName);
});
program.command("generate").alias("g").description("\u751F\u6210\u4EE3\u7801").action(genCode);
program.command("update").alias("u").description(`\u66F4\u65B0 ${PKG_NAME} \u81F3\u6700\u65B0\u7248\u672C`).action(() => updateVersion_default(true));
program.command("scan").alias("sn").description("\u626B\u63CF\u5E9F\u5F03\u63A5\u53E3").action(scan);
program.command("open").alias("o").description("\u751F\u6210\u63A5\u53E3\u53D8\u66F4\u8BB0\u5F55\u62A5\u8868").action(genReport);
program.parse(process.argv);
if (process.argv.length === 2) {
  program.outputHelp();
}
process.on("unhandledRejection", (error2) => {
  console.error("unhandledRejection", error2);
  process.exit(1);
});
